*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
scwin.vScrenID = "ULDSTF08200.xml";
scwin.procJob = "";
scwin.vViewCorrYnTyp = '3'; //마감송수신 
scwin.pMngId = js_id;
scwin.pJobTitl = js_jobtitl; //권한
scwin.vBzProcsNo;
scwin.vIsuCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var urltaskdd = "&TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
    var url;

    //상장일자 가져오기 (TBLD_BZ_CALND 테이블사용)
    url = "/ElwListedReceive.do?method=getElwListingListDd&inputMessageId=ELW_LISTING_TR_SEND_LOG_INOUT";
    url += urltaskdd;
    dts_Get_ListDD.DataID = encodeURI(url);
    dts_Get_ListDD.Reset();

    //마감이력가져오기 - etn으로 수정해야함
    url = "/etn/EtnNewList.do?method=searchLosslmtFinalLog&inputMessageId=LOSSLMT_ETN_FINAL_LOG";
    url += urltaskdd;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //손실제한ETN 신규상장 내역
        var url_new = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LOSSLMT_ETN_NEWLISTING_SEARCH_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.losslmtetn.newlst.select.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_LIST_DD);
        url_new += "&SCREN_ID=" + scwin.vScrenID;
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_New_Proc.DataID = encodeURI(url_new);
        dts_New_Proc.Reset();
        $c.cm.ShowWin(grd_New_Proc);

        //상환주기 내역
        var url_add = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LOSSLMT_ETN_NEWLISTING_REDMPT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.losslmtetn.newlst.select.redmpt.condition" + "&{P}param01=" + scwin.vBzProcsNo;
        url_add += "&SCREN_ID=" + scwin.vScrenID;
        url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Add_Proc.DataID = encodeURI(url_add);
        dts_Add_Proc.Reset();
        $c.cm.ShowWin(grd_Add_Proc);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        //손실제한ETN 신규상장 마감처리내역
        var url_new = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LOSSLMT_ETN_NEWLISTING_SEARCH_RV_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.losslmtetn.newlst.select.list.rv" + "&{P}param01=" + $c.stf.getObjectValue(edt_TASK_DD);
        url_new += "&SCREN_ID=" + scwin.vScrenID;
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_New_Search.DataID = encodeURI(url_new);
        dts_New_Search.Reset();
        $c.cm.ShowWin(grd_New_Search);

        //상환주기 마감처리내역
        var url_add = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LOSSLMT_ETN_NEWLISTING_REDMPT_RV_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.losslmtetn.newlst.select.redmpt.rv.all" + "&{P}param01=" + $c.stf.getObjectValue(edt_TASK_DD);
        url_add += "&SCREN_ID=" + scwin.vScrenID;
        url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Add_Search.DataID = encodeURI(url_add);
        dts_Add_Search.Reset();
        $c.cm.ShowWin(grd_Add_Search);
    }
};




//신규상장 그리드 클릭시 상환주기 가져오기
scwin.fn_SearchRedmpt = function() {
    var url_add = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LOSSLMT_ETN_NEWLISTING_REDMPT_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.losslmtetn.newlst.select.redmpt.condition" + "&{P}param01=" + scwin.vBzProcsNo;
    url_add += "&SCREN_ID=" + scwin.vScrenID;
    url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Add_Proc.DataID = encodeURI(url_add);
    dts_Add_Proc.Reset();
    $c.cm.ShowWin(grd_Add_Proc);
};


//마감처리내역 신규상장 그리드 클릭시 상환주기(전송내역) 가져오기
scwin.fn_SearchRedmptRv = function() {
    var url_add = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LOSSLMT_ETN_NEWLISTING_REDMPT_RV_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstproc.losslmtetn.newlst.select.redmpt.rv.sel" + "&{P}param01=" + $c.stf.getObjectValue(edt_TASK_DD) + "&{P}param02=" + scwin.vIsuCd;
    url_add += "&SCREN_ID=" + scwin.vScrenID;
    url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Add_Search.DataID = encodeURI(url_add);
    dts_Add_Search.Reset();
    $c.cm.ShowWin(grd_Add_Search);
};


//재마감 버튼 클릭시 (현업관리자만 버튼보임)
scwin.fn_recls = function() {
    scwin.procJob = "재마감처리";
    if (!scwin.fn_checkProcDt(scwin.procJob)) return;
    var res = window.confirm("재마감처리를 선택 하셨습니다.\n재마감처리는 이전마감처리기록을 삭제하므로\n재마감처리후 다시 마감처리를 하셔야 됩니다.\n\n재마감처리를 하시겠습니까?");
    if (res) {
        scwin.fn_trSetHeader();
        trs_Cls.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=losslmtReClsProcsSave";
        trs_Cls.KeyName = "toinb_dataid4";
        trs_Cls.KeyValue = "JSP(I:pInput=dts_Cls)";
        trs_Cls.Post();
    }
};
scwin.fn_trSetHeader = function() {
    dts_Cls.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LOSSLMT_ETN_FINAL_LOG_EMP";
    dts_Cls.reset();
    dts_Cls.insertRow();
};


//담당자 확인 버튼 클릭시
scwin.fn_revw = function() {
    scwin.procJob = "담당자 확인";
    if (!scwin.fn_checkProcDt(scwin.procJob)) return;
    res = window.confirm("담당자 확인 하시겠습니까?");
    if (res) {
        scwin.fn_trs_revw();
    }
};



//담당자 확인
scwin.fn_trs_revw = function() {
    scwin.fn_trSetHeader();
    dts_Cls.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    trs_revw.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=losslmtRevwProcsSave";
    trs_revw.KeyName = "toinb_dataid4";
    trs_revw.KeyValue = "JSP(I:pInput=dts_Cls)";
    trs_revw.Post();
};


//팀장승인 버튼 클릭시
scwin.fn_cls = function() {
    if ($c.stf.getObjectValue(txb_APPROV_TM) == "") {
        $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return true;
    }
    scwin.procJob = "마감처리";
    //if (! fn_checkProcDt(procJob))  return;
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }
    var commit = window.confirm("마감처리 하시겠습니까?");
    if (commit) {
        scwin.fn_trs();
    }
};



//팀장승인 
scwin.fn_trs = function() {
    scwin.fn_trSetHeader();
    dts_Cls.setCellData(1, "LIST_DD", $c.stf.getObjectValue(edt_LIST_DD));
    dts_Cls.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    trs_Cls.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=losslmtClsProcsSave";
    trs_Cls.KeyName = "toinb_dataid4";
    trs_Cls.KeyValue = "JSP(I:pInput=dts_Cls)";
    trs_Cls.Post();
};


// 담당자 승인, 팀장승인, 재마감처리 
scwin.buttonSetDis = function() {
    //담당자일때
    if (scwin.pJobTitl == "03") {
        if ($c.stf.getObjectValue(txb_BZ_CLS_TM) != "") {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        } else {
            if ($c.stf.getObjectValue(txb_APPROV_EMP_NM) == "") {
                //담당자확인을 않했을 경우
                btn_Revw.src = "../img/btn/btn_revw.gif";
                btn_Revw.setDisabled(false);
            } else {
                btn_Revw.src = "../img/btn/btn_revw_d.gif";
                btn_Revw.setDisabled(true);
            }
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        }
        //	showObj(btn_Recls, false);

    }
    //팀장일때 - 마감처리
    else {
        if ($c.stf.getObjectValue(txb_BZ_CLS_TM) != "") {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        } else {
            if ($c.stf.getObjectValue(txb_APPROV_EMP_NM) == "") {
                //담당자확인을 않했을 경우		
                btn_Revw.src = "../img/btn/btn_revw.gif";
                btn_Revw.setDisabled(false);
                btn_Cls.src = "../img/btn_BosApv_d.gif";
                btn_Cls.setDisabled(true);
            } else {
                btn_Revw.src = "../img/btn/btn_revw_d.gif";
                btn_Revw.setDisabled(true);
                btn_Cls.src = "../img/btn_BosApv.gif";
                btn_Cls.setDisabled(false);
            }
        }
        //	showObj(btn_Recls, false);

    }

    //재마감 처리 버튼 - 시스템 관리자 
    if (js_dep_cd == 'ZSYS') {
        btn_Recls.src = "../img/btn_ReCls.gif";
        btn_Recls.setDisabled(false);
        $c.stf.showObj(btn_Recls, true);
    } else {
        $c.stf.showObj(btn_Recls, false);
    }
};
scwin.fn_checkProcDt = function(str) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var pCheck = true;
    if ($c.stf.getObjectValue(edt_TASK_DD) != vCurDate) {
        $c.win.alert("[마감일]이 현재일경우만 '" + str + "'를 할수 있습니다.");
        pCheck = false;
    }
    if (pCheck) {
        for (var i = 1; i <= dts_New_Proc.getTotalRow(); i++) {
            if (dts_New_Proc.getCellData(i, "ISU_MKTPARTC_NO") == "") {
                $c.win.alert("발행회사명에 대한 시장참가자번호가 없는 종목이 있습니다. 시스템관리자에게 문의바랍니다.");
                pCheck = false;
                break;
            }

            //if ( dts_New_Proc.NameString(i,"ISU_SHRS") <= 0 )

            //{

            //	alert("LP보유량이 '0'인 종목이 있습니다. 확인하여주십시오.");

            //	pCheck = false;

            //	break;

            //}

        }
    }
    return pCheck;
};
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_New_Proc, "손실제한ETN 신규상장 마감처리목록", "", "8");
        $c.data.downloadGridViewExcel(grd_Add_Proc, "손실제한ETN 상환주기 마감처리목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_New_Search, "손실제한ETN 신규상장 송신목록", "", "8");
        $c.data.downloadGridViewExcel(grd_Add_Search, "손실제한ETN 추가상장 송신목록", "", "8");
    }
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    if (nIndex == "1") {
        edt_TASK_DD.setReadOnly(true);
        img_TASK_DD.setDisabled(true);
        edt_TASK_DD.ReadOnlyBackColor = "#b9d4f7";
        edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    } else if (nIndex == "2") {
        edt_TASK_DD.setReadOnly(false);
        img_TASK_DD.setDisabled(false);
    }
    scwin.fn_list_sync();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_ProcClose_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_ProcExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.btn_SearchExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.img_TASK_DD_onclick = function() {
    popUpCalendar2(edt_TASK_DD);
};
scwin.dts_Get_ListDD_OnLoadError = function() {
    //alert_error(dts_Get_ListDD);
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_New_Proc_OnLoadError = function() {
    //alert_error(dts_New_Proc);
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_New_Search_OnLoadError = function() {
    //alert_error(dts_New_Search);
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_Add_Proc_OnLoadError = function() {
    //alert_error(dts_Add_Proc);
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_Add_Search_OnLoadError = function() {
    //alert_error(dts_Add_Search);
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_IsuDelChk_OnLoadError = function() {
    $c.stf.alert_error(dts_IsuDelChk);
};
scwin.dts_CorrYn_OnLoadError = function() {
    $c.stf.alert_error(dts_CorrYn);
};
scwin.dts_New_Proc_OnLoadCompleted = function(rowcount) {
    edt_New_Proc_TotalCnt.setValue("총 " + dts_New_Proc.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_New_Proc);
    dts_Add_Proc.removeAll();
    scwin.vBzProcsNo = dts_New_Proc.getCellData(0, 'BZ_PROCS_NO');
    scwin.fn_SearchRedmpt();
    scwin.buttonSetDis();
};
scwin.dts_New_Search_OnLoadCompleted = function(rowcount) {
    edt_New_Search_TotalCnt.setValue("총 " + dts_New_Search.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_New_Search);
};
scwin.dts_Add_Proc_OnLoadCompleted = function(rowcount) {
    edt_Add_Proc_TotalCnt.setValue("총 " + dts_Add_Proc.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_Add_Proc);
};
scwin.dts_Add_Search_OnLoadCompleted = function(rowcount) {
    edt_Add_Search_TotalCnt.setValue("총 " + dts_Add_Search.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_Add_Search);
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.btn_ProcClose_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_SearchClose_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //재마감 처리 관리자만 보일 수 있도록 
    if (js_dep_cd == 'ZSYS') {
        btn_Recls.src = "../img/btn_ReCls.gif";
        btn_Recls.setDisabled(false);
        $c.stf.showObj(btn_Recls, true);
    } else {
        $c.stf.showObj(btn_Recls, false);
    }

    //담당자, 팀장확인 버튼
    btn_Revw.src = "../img/btn/btn_revw_d.gif";
    btn_Revw.setDisabled(true);
    btn_Cls.src = "../img/btn_BosApv_d.gif";
    btn_Cls.setDisabled(true);

    //마감일
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_TASK_DD, vCurDate);
    MaxTab_01.setSelectedTabIndex(1);
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.btn_Recls_onclick = function() {
    scwin.fn_recls();
};
scwin.btn_Revw_onclick = function() {
    scwin.fn_revw();
};
scwin.btn_Cls_onclick = function() {
    scwin.fn_cls();
};
scwin.trs_revw_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
};
scwin.trs_revw_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.trs_Cls_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
};
scwin.trs_Cls_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.grd_New_Proc_OnClick = function(row, colid) {
    if (row == 0) return;
    dts_Add_Proc.removeAll();
    scwin.vBzProcsNo = dts_New_Proc.getCellData(row, 'BZ_PROCS_NO');
    scwin.fn_SearchRedmpt();
};
scwin.grd_New_Search_OnClick = function(row, colid) {
    if (row == 0) return;
    dts_Add_Search.removeAll();
    scwin.vIsuCd = dts_New_Search.getCellData(row, 'ISU_CD');
    scwin.fn_SearchRedmptRv();
};
